<script setup>
import { ref } from 'vue';import { useClinicContextStore } from '../../stores/clinicContext';import { doctorService } from '../../services/doctors';import FormErrors from '../ui/FormErrors.vue';
const props=defineProps({doctor:Object});const emit=defineEmits(['changed']);const context=useClinicContextStore();const confirm=ref(false),busy=ref(false),error=ref(null);
async function change(){busy.value=true;error.value=null;try{await doctorService.status(props.doctor.id,props.doctor.status==='active'?'deactivate':'activate');confirm.value=false;emit('changed');}catch(e){error.value=e;}finally{busy.value=false;}}
</script>
<template><details class="patient-actions"><summary aria-label="More clinician actions">⋮</summary><div><RouterLink :to="`/app/doctors/${doctor.id}`">View profile</RouterLink><RouterLink v-if="context.can('doctors.update') && doctor.can_manage_branches" :to="`/app/doctors/${doctor.id}/edit`">Edit</RouterLink><RouterLink v-if="context.can('doctors.schedule.view')" :to="`/app/doctors/${doctor.id}/schedule`">Manage schedule</RouterLink><RouterLink v-if="context.can('doctors.leave.manage')" :to="`/app/doctors/${doctor.id}/schedule?leave=1`">Set on leave</RouterLink><button v-if="context.can('doctors.deactivate') && doctor.can_manage_branches" @click="confirm=true">{{doctor.status==='active'?'Deactivate':'Activate'}}</button></div></details><Teleport to="body"><div v-if="confirm" class="modal-backdrop"><section class="modal-card" role="dialog" aria-modal="true" aria-labelledby="doctor-status-title"><h2 id="doctor-status-title" class="text-xl font-bold">{{doctor.status==='active'?'Deactivate':'Activate'}} {{doctor.full_name}}?</h2><p class="my-4 text-slate-500">This changes the clinical profile status. The linked user account is managed separately.</p><FormErrors :error="error"/><div class="mt-6 flex justify-end gap-3"><button class="btn-secondary" :disabled="busy" @click="confirm=false">Cancel</button><button class="btn" :disabled="busy" @click="change">Confirm</button></div></section></div></Teleport></template>
